const LANG_KEY = "clcat.lang.v1";
let UI_LANG = "lv";
try { const l = localStorage.getItem(LANG_KEY); if (l === "ru" || l === "lv") UI_LANG = l; } catch (e) { /* default */ }
globalThis.CL_TR = (s) => (UI_LANG === "ru" ? s : (Object.prototype.hasOwnProperty.call(I18N_LV, s) ? I18N_LV[s] : s));
function applyStaticText() {
  document.documentElement.lang = UI_LANG;
  document.querySelectorAll("[data-tr]").forEach(el => { el.textContent = globalThis.CL_TR(el.dataset.tr); });
  document.querySelectorAll("[data-tr-aria]").forEach(el => { el.setAttribute("aria-label", globalThis.CL_TR(el.dataset.trAria)); });
}
function setLang(l) {
  UI_LANG = l === "ru" ? "ru" : "lv";
  try { localStorage.setItem(LANG_KEY, UI_LANG); } catch (e) { /* ignore */ }
  applyStaticText();
}
